const envelope = $input || {};
const text = (value) => (typeof value === 'string' ? value.trim() : '');
const envelopeKeys = new Set(['pluginId', 'widgetId', 'product', 'resource', 'submittedBy', 'submittedAt', 'action', 'fields']);
const unknownEnvelope = Object.keys(envelope).filter((key) => !envelopeKeys.has(key));
if (unknownEnvelope.length) throw new Error('unknown_envelope_fields:' + unknownEnvelope.join(','));
const product = text(envelope.product);
const resource = text(envelope.resource);
const submittedBy = text(envelope.submittedBy);
if (!submittedBy) throw new Error('submitted_by_required');
const fields = envelope.fields && typeof envelope.fields === 'object' && !Array.isArray(envelope.fields) ? envelope.fields : null;
if (!fields) throw new Error('fields_required');

if (product !== 'city') throw new Error('unsupported_product');
if (resource !== 'maintenance') throw new Error('unsupported_resource');
const allowed = new Set(["asset_id","title","description","priority","scheduled_date"]);
const unknown = Object.keys(fields).filter((key) => !allowed.has(key));
if (unknown.length) throw new Error('unknown_fields:' + unknown.join(','));
const assetId = text(fields.asset_id);
if (!assetId || assetId.length > 128) throw new Error('asset_id_required_max_128');
const title = text(fields.title);
if (!title || title.length > 200) throw new Error('title_required_max_200');
const description = text(fields.description);
if (description.length > 4000) throw new Error('description_max_4000');
const priority = text(fields.priority) || 'medium';
if (!['low', 'medium', 'high', 'critical', 'urgent'].includes(priority)) throw new Error('priority_invalid');
const scheduled = text(fields.scheduled_date);
if (scheduled && !/^\d{4}-\d{2}-\d{2}(?:T[0-9:.]+Z?)?$/.test(scheduled)) throw new Error('scheduled_date_invalid');
const binding = { product, resource, dataset: 'city-maintenance', recordType: 'Maintenance', operation: 'maintenance.create' };
const record = { type: 'Maintenance', asset_id: assetId, title, description, priority, status: 'scheduled', scheduled_date: scheduled || $now, created_at: $now, updated_at: $now };

const audit = {
  product,
  resource,
  operation: 'maintenance.create',
  pluginId: text(envelope.pluginId),
  widgetId: text(envelope.widgetId),
  submittedBy,
  submittedAt: text(envelope.submittedAt) || $now,
};

return {
  body: { data: record, publish: false },
  audit,
  binding,
};
